"""Studio Shin - script library backend.

Storage (automatic):
  * Upstash Redis  -> if UPSTASH_REDIS_REST_URL/TOKEN (or Vercel's KV_REST_API_URL/TOKEN) are set
  * a JSON file    -> otherwise (needs a persistent volume, e.g. on Wasmer)
Works on Vercel, Wasmer, Render, Koyeb... any host that runs Flask.
"""
import os, re, base64, json, hmac, hashlib, time, ssl, urllib.request
from flask import Flask, request, jsonify, send_from_directory, make_response

HERE = os.path.dirname(os.path.abspath(__file__))
USER = os.environ.get("ADMIN_USER", "StudShin")
PASS = os.environ.get("ADMIN_PASS", "")             # set in the host's dashboard, NOT in code
SECRET = os.environ.get("SECRET") or PASS

# --- storage config ---
RURL = (os.environ.get("UPSTASH_REDIS_REST_URL") or os.environ.get("KV_REST_API_URL") or "").rstrip("/")
RTOK = os.environ.get("UPSTASH_REDIS_REST_TOKEN") or os.environ.get("KV_REST_API_TOKEN") or ""
USE_REDIS = bool(RURL and RTOK)
KEY = "studio-shin:scripts"
DATA = os.environ.get("DATA_DIR", "/data")
FILE = os.path.join(DATA, "scripts.json")
MAX_REDIS_BYTES = 900_000                           # stay under Upstash's request size limit

def _make_ssl_context():
    """Some hosts (e.g. Wasmer) have no system CA certificates, so use certifi's bundle."""
    if os.environ.get("REDIS_SSL_VERIFY") == "0":      # last resort only - NOT recommended
        return ssl._create_unverified_context()
    try:
        import certifi
        return ssl.create_default_context(cafile=certifi.where())
    except Exception:
        return ssl.create_default_context()


SSL_CTX = _make_ssl_context()

# --- security settings (all can be overridden with environment variables) ---
TOKEN_TTL = int(os.environ.get("TOKEN_TTL", "43200"))          # login lasts 12 hours
MAX_FAILS = int(os.environ.get("LOCK_MAX_FAILS", "3"))         # wrong passwords before lock
LOCK_SECONDS = int(os.environ.get("LOCK_SECONDS", "9000"))     # lock time: 2 hours 30 minutes
HOPS = max(1, int(os.environ.get("TRUST_PROXY_HOPS", "1")))    # proxies in front of the app
FAIL_PFX, LOCK_PFX = "studio-shin:fail:", "studio-shin:lock:"
LOCKFILE = os.path.join(DATA, "locks.json")

app = Flask(__name__)
app.config["MAX_CONTENT_LENGTH"] = 8 * 1024 * 1024


def rcmd(*cmd):
    """Run one Redis command through Upstash's REST API (no extra packages needed)."""
    req = urllib.request.Request(
        RURL, data=json.dumps(list(cmd)).encode("utf-8"), method="POST",
        headers={"Authorization": "Bearer " + RTOK, "Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=8, context=SSL_CTX) as r:
        out = json.loads(r.read().decode("utf-8"))
    if isinstance(out, dict) and out.get("error"):
        raise OSError(out["error"])
    return out.get("result") if isinstance(out, dict) else None


def load_scripts():
    if USE_REDIS:
        raw = rcmd("GET", KEY)
        return json.loads(raw) if raw else None
    try:
        with open(FILE, encoding="utf-8") as f:
            return json.load(f)
    except FileNotFoundError:
        return None


def fit_size(items, limit):
    """Drop the oldest saved versions until everything fits in `limit` bytes."""
    def size():
        return len(json.dumps(items, ensure_ascii=False).encode("utf-8"))
    while size() > limit:
        with_hist = [x for x in items if x.get("hist")]
        if not with_hist:
            raise ValueError("too big (max about 900KB in total)")
        w = max(with_hist, key=lambda x: len(x["hist"]))
        w["hist"].pop()
        if not w["hist"]:
            del w["hist"]


def store_scripts(items):
    if USE_REDIS:
        fit_size(items, MAX_REDIS_BYTES)
    text = json.dumps(items, ensure_ascii=False)
    if USE_REDIS:
        rcmd("SET", KEY, text)
        return
    os.makedirs(DATA, exist_ok=True)
    tmp = FILE + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        f.write(text)
    os.replace(tmp, FILE)


# ---------- visitor counter ----------
V_KEY, U_KEY = "studio-shin:views", "studio-shin:uniq"
STATS_FILE = os.path.join(DATA, "stats.json")
BOTS = ("bot", "spider", "crawl", "curl", "wget", "python-requests", "slurp", "facebookexternalhit")


def rpipe(cmds):
    req = urllib.request.Request(
        RURL + "/pipeline", data=json.dumps(cmds).encode("utf-8"), method="POST",
        headers={"Authorization": "Bearer " + RTOK, "Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=8, context=SSL_CTX) as r:
        out = json.loads(r.read().decode("utf-8"))
    res = []
    for o in out:
        if isinstance(o, dict) and o.get("error"):
            raise OSError(o["error"])
        res.append(o.get("result") if isinstance(o, dict) else None)
    return res


def redis_many(cmds):
    try:
        return rpipe(cmds)                      # one request for all commands
    except Exception:
        return [rcmd(*c) for c in cmds]         # fallback: one by one


def visitor_id():
    """Anonymous id: salted hash of IP + browser. The raw IP is never stored."""
    raw = (SECRET or "salt") + "|" + client_ip() + "|" + request.headers.get("User-Agent", "")
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()[:20]


def is_bot():
    ua = request.headers.get("User-Agent", "").lower()
    return (not ua) or any(k in ua for k in BOTS)


def _file_stats():
    try:
        with open(STATS_FILE, encoding="utf-8") as f:
            d = json.load(f)
        return {"views": int(d.get("views", 0)), "seen": list(d.get("seen", []))}
    except Exception:
        return {"views": 0, "seen": []}


def read_stats():
    if USE_REDIS:
        v, u = redis_many([["GET", V_KEY], ["PFCOUNT", U_KEY]])
        return int(v or 0), int(u or 0)
    d = _file_stats()
    return d["views"], len(d["seen"])


def bump(vid):
    if USE_REDIS:
        v, _, u = redis_many([["INCR", V_KEY], ["PFADD", U_KEY, vid], ["PFCOUNT", U_KEY]])
        return int(v), int(u)
    d = _file_stats()
    d["views"] += 1
    if vid not in d["seen"] and len(d["seen"]) < 50000:
        d["seen"].append(vid)
    try:
        os.makedirs(DATA, exist_ok=True)
        tmp = STATS_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(d, f)
        os.replace(tmp, STATS_FILE)
    except OSError:
        pass
    return d["views"], len(d["seen"])


# ---------- site settings (contact links) ----------
SKEY = "studio-shin:site"
SFILE = os.path.join(DATA, "site.json")
LINK_OK = ("http://", "https://", "mailto:")


def load_site():
    if USE_REDIS:
        raw = rcmd("GET", SKEY)
        return json.loads(raw) if raw else {"links": []}
    try:
        with open(SFILE, encoding="utf-8") as f:
            return json.load(f)
    except FileNotFoundError:
        return {"links": []}


def store_site(d):
    text = json.dumps(d, ensure_ascii=False)
    if USE_REDIS:
        rcmd("SET", SKEY, text)
        return
    os.makedirs(DATA, exist_ok=True)
    tmp = SFILE + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        f.write(text)
    os.replace(tmp, SFILE)


def clean_script(s):
    if not isinstance(s, dict) or not all(isinstance(s.get(k), str) for k in ("name", "zh", "en", "code")):
        return None
    if len(s["name"]) > 80 or len(s["zh"]) > 500 or len(s["en"]) > 500 or len(s["code"]) > 400_000:
        return None
    out = {k: s[k] for k in ("name", "zh", "en", "code")}
    t = s.get("t")
    if isinstance(t, int) and not isinstance(t, bool):
        out["t"] = t
    tg = s.get("tags")
    if isinstance(tg, list):
        seen = []
        for x in tg[:10]:
            if isinstance(x, str):
                x = x.strip()
                if x and len(x) <= 20 and x not in seen:
                    seen.append(x)
        if seen:
            out["tags"] = seen[:5]
    if s.get("pin") is True:
        out["pin"] = True
    if isinstance(s.get("doc"), str) and len(s["doc"]) <= 4000:
        out["doc"] = s["doc"]
    h = s.get("hist")
    if isinstance(h, list):
        hh = []
        for x in h[:5]:
            if (isinstance(x, dict) and isinstance(x.get("code"), str) and len(x["code"]) <= 400_000
                    and isinstance(x.get("t"), int) and not isinstance(x.get("t"), bool)):
                hh.append({"t": x["t"], "code": x["code"]})
        if hh:
            out["hist"] = hh
    return out


def client_ip():
    """Client address. Uses the X-Forwarded-For entry added by the nearest trusted proxy."""
    xs = [x.strip() for x in request.headers.get("X-Forwarded-For", "").split(",") if x.strip()]
    if xs:
        return xs[-HOPS] if len(xs) >= HOPS else xs[0]
    return request.remote_addr or ""


def client_key():
    return hashlib.sha256(((SECRET or "s") + "|" + client_ip()).encode("utf-8")).hexdigest()[:20]


def _locks():
    try:
        with open(LOCKFILE, encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {}


def _save_locks(d):
    try:
        os.makedirs(DATA, exist_ok=True)
        tmp = LOCKFILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(d, f)
        os.replace(tmp, LOCKFILE)
    except OSError:
        pass


def lock_left(k):
    """Seconds this client is still locked out (0 = not locked)."""
    if USE_REDIS:
        v = int(rcmd("TTL", LOCK_PFX + k) or -2)
        return v if v > 0 else 0
    return max(0, int(_locks().get(k, {}).get("until", 0) - time.time()))


def add_fail(k):
    if USE_REDIS:
        n, _ = redis_many([["INCR", FAIL_PFX + k], ["EXPIRE", FAIL_PFX + k, LOCK_SECONDS]])
        return int(n)
    d = _locks()
    e = d.setdefault(k, {})
    e["fails"] = int(e.get("fails", 0)) + 1
    _save_locks(d)
    return e["fails"]


def set_lock(k):
    if USE_REDIS:
        redis_many([["SET", LOCK_PFX + k, "1", "EX", LOCK_SECONDS], ["DEL", FAIL_PFX + k]])
        return
    d = _locks()
    d[k] = {"until": time.time() + LOCK_SECONDS, "fails": 0}
    _save_locks(d)


def clear_fail(k):
    if USE_REDIS:
        rcmd("DEL", FAIL_PFX + k)
        return
    d = _locks()
    if k in d and not d[k].get("until", 0) > time.time():
        del d[k]
        _save_locks(d)


def _sign(exp):
    return hmac.new(SECRET.encode(), ("admin-v2:%d" % exp).encode(), hashlib.sha256).hexdigest()


def token():
    exp = int(time.time()) + TOKEN_TTL
    return "%d.%s" % (exp, _sign(exp))


def authed():
    if not SECRET:
        return False
    got = request.headers.get("Authorization", "").replace("Bearer ", "", 1)
    try:
        exp_s, sig = got.split(".", 1)
        exp = int(exp_s)
    except ValueError:
        return False
    return exp > time.time() and hmac.compare_digest(sig, _sign(exp))


CSP = ("default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; "
       "font-src https://fonts.gstatic.com; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'; "
       "base-uri 'none'; form-action 'none'; object-src 'none'")


@app.after_request
def secure(resp):
    if request.path in ("/og.jpg", "/icon.png"):
        resp.headers["Cache-Control"] = "public, max-age=86400"
    else:
        resp.headers["Cache-Control"] = "no-store"     # always fresh pages/data
    resp.headers["X-Content-Type-Options"] = "nosniff"
    resp.headers["X-Frame-Options"] = "DENY"
    resp.headers["Referrer-Policy"] = "strict-origin-when-cross-origin"
    resp.headers["Permissions-Policy"] = "camera=(), microphone=(), geolocation=()"
    resp.headers["Content-Security-Policy"] = CSP
    if request.is_secure or request.headers.get("X-Forwarded-Proto", "").startswith("https"):
        resp.headers["Strict-Transport-Security"] = "max-age=31536000"
    return resp


def origin():
    """Absolute site address for share previews (set SITE_URL to force one)."""
    base = os.environ.get("SITE_URL", "").rstrip("/")
    if base:
        return base
    proto = request.headers.get("X-Forwarded-Proto", "").split(",")[0].strip() or request.scheme
    host = request.headers.get("X-Forwarded-Host", "").split(",")[0].strip() or request.host
    if proto not in ("http", "https") or not re.fullmatch(r"[A-Za-z0-9.\-:\[\]]+", host or ""):
        return ""
    return proto + "://" + host


@app.get("/")
def index():
    with open(os.path.join(HERE, "index.html"), encoding="utf-8") as f:
        html = f.read().replace("__ORIGIN__", origin())
    resp = make_response(html)
    resp.mimetype = "text/html"
    return resp


@app.get("/og.jpg")
def og_image():
    return app.response_class(OG_JPG, mimetype="image/jpeg")


@app.get("/icon.png")
def icon_image():
    return app.response_class(ICON_PNG, mimetype="image/png")


@app.get("/api/scripts")
def get_scripts():
    try:
        data = load_scripts()
    except Exception as e:
        return jsonify(error="storage: %s" % e), 502
    if data is None:
        return jsonify(None), 404
    return jsonify(data)


def _locked(sec):
    r = jsonify(error="locked", retry_after=sec)
    r.status_code = 429
    r.headers["Retry-After"] = str(sec)
    return r


@app.post("/api/login")
def login():
    d = request.get_json(silent=True) or {}
    k = client_key()
    try:
        left = lock_left(k)
    except Exception:
        return jsonify(error="unavailable"), 503
    if left > 0:
        return _locked(left)
    ok = (PASS and hmac.compare_digest(str(d.get("user", "")), USER)
          and hmac.compare_digest(str(d.get("pass", "")), PASS))
    if ok:
        try:
            clear_fail(k)
        except Exception:
            pass
        return jsonify(token=token())
    time.sleep(1.5)  # slow down guessing
    try:
        n = add_fail(k)
        if n >= MAX_FAILS:
            set_lock(k)
            return _locked(LOCK_SECONDS)
    except Exception:
        return jsonify(error="unavailable"), 503
    return jsonify(error="bad", left=MAX_FAILS - n), 401


@app.post("/api/scripts")
def save_scripts():
    if not authed():
        return jsonify(error="auth"), 401
    d = request.get_json(silent=True)
    if not isinstance(d, list) or not 0 < len(d) <= 100:
        return jsonify(error="invalid"), 400
    clean = []
    for s in d:
        c = clean_script(s)
        if c is None:
            return jsonify(error="invalid or too big"), 400
        clean.append(c)
    try:
        store_scripts(clean)
    except ValueError as e:
        return jsonify(error=str(e)), 400
    except Exception as e:
        return jsonify(error="storage: %s" % (getattr(e, "strerror", None) or e)), 500
    return jsonify(ok=True)


@app.post("/api/visit")
def visit():
    """Called once per browser tab session. Owner (logged in) and bots are not counted."""
    try:
        v, u = read_stats() if (authed() or is_bot()) else bump(visitor_id())
    except Exception:
        return jsonify(error="stats"), 502
    return jsonify(views=v, unique=u)


@app.get("/api/stats")
def stats():
    try:
        v, u = read_stats()
    except Exception:
        return jsonify(error="stats"), 502
    return jsonify(views=v, unique=u)


@app.get("/api/site")
def get_site():
    try:
        return jsonify(load_site())
    except Exception:
        return jsonify({"links": []})


@app.post("/api/site")
def save_site():
    if not authed():
        return jsonify(error="auth"), 401
    d = request.get_json(silent=True) or {}
    links = d.get("links")
    if not isinstance(links, list) or len(links) > 10:
        return jsonify(error="invalid"), 400
    clean = []
    for l in links:
        if (not isinstance(l, dict) or not isinstance(l.get("label"), str) or not isinstance(l.get("url"), str)
                or not l["label"].strip() or len(l["label"]) > 30 or len(l["url"]) > 300
                or not l["url"].lower().startswith(LINK_OK)):
            return jsonify(error="invalid link"), 400
        clean.append({"label": l["label"].strip(), "url": l["url"].strip()})
    try:
        store_site({"links": clean})
    except Exception as e:
        return jsonify(error="storage: %s" % e), 500
    return jsonify(ok=True)


@app.get("/api/health")
def health():
    """Open /api/health in the browser to check the setup (shows no secrets)."""
    info = dict(storage="redis" if USE_REDIS else "file", admin_pass_set=bool(PASS),
                proxy_ip_header=bool(request.headers.get("X-Forwarded-For")))
    try:
        if USE_REDIS:
            info["storage_ok"] = rcmd("PING") == "PONG"
        else:
            os.makedirs(DATA, exist_ok=True)
            t = os.path.join(DATA, ".w")
            open(t, "w").close(); os.remove(t)
            info["storage_ok"] = True
            info["data_dir"] = DATA
        info["has_saved_scripts"] = load_scripts() is not None
    except Exception as e:
        info["storage_ok"] = False
        info["storage_error"] = str(e)[:200]
    return jsonify(info)


